use matrix_rotate::rotate;

#[test]
fn test_1x1() {
    let mut m = vec![vec![1]];
    rotate(&mut m);
    assert_eq!(m, vec![vec![1]]);
}

#[test]
fn test_2x2() {
    let mut m = vec![vec![1, 2], vec![3, 4]];
    rotate(&mut m);
    assert_eq!(m, vec![vec![3, 1], vec![4, 2]]);
}

#[test]
fn test_3x3() {
    let mut m = vec![vec![1, 2, 3], vec![4, 5, 6], vec![7, 8, 9]];
    rotate(&mut m);
    assert_eq!(m, vec![vec![7, 4, 1], vec![8, 5, 2], vec![9, 6, 3]]);
}

#[test]
fn test_4x4() {
    let mut m = vec![
        vec![5, 1, 9, 11],
        vec![2, 4, 8, 10],
        vec![13, 3, 6, 7],
        vec![15, 14, 12, 16],
    ];
    rotate(&mut m);
    assert_eq!(m, vec![
        vec![15, 13, 2, 5],
        vec![14, 3, 4, 1],
        vec![12, 6, 8, 9],
        vec![16, 7, 10, 11],
    ]);
}
